            tree[node] += lazy[node];
            if (start != end) {  // not a leaf
                lazy[2*node] += lazy[node];
                lazy[2*node+1] += lazy[node];
            }
            lazy[node] = 0;
        }
    }

    void updateRange(int node, int start, int end, int l, int r, long long val) {
        push(node, start, end);
        if (start > r || end < l) return;

        if (start >= l && end <= r) {
            lazy[node] += val;
            push(node, start, end);
            return;
        }

        int mid = (start + end) / 2;
        updateRange(2*node, start, mid, l, r, val);
        updateRange(2*node+1, mid+1, end, l, r, val);

        push(2*node, start, mid);
        push(2*node+1, mid+1, end);
        tree[node] = max(tree[2*node], tree[2*node+1]);
    }

    long long queryRange(int node, int start, int end, int l, int r) {
        if (start > r || end < l) return LLONG_MIN;
        push(node, start, end);
        if (start >= l && end <= r) return tree[node];

        int mid = (start + end) / 2;
        return max(queryRange(2*node, start, mid, l, r),
                  queryRange(2*node+1, mid+1, end, l, r));
    }

public:
    LazySegmentTree(vector<int>& arr) {
        n = arr.size();
        tree.resize(4 * n);
        lazy.resize(4 * n);
        // Build tree (omitted for brevity)
    }

    void update(int l, int r, long long val) {
        updateRange(1, 0, n-1, l, r, val);
    }

    long long query(int l, int r) {
        return queryRange(1, 0, n-1, l, r);
    }
};
```

## Proof of Complexity Bound

**Theorem:** After k range updates and q range queries, the total number of node updates is O(k log n + q log n).

**Proof:** 
- **Range Updates:** Each range update creates lazy values at O(log n) nodes (the minimal set of nodes that cover the range). Total: O(k log n) node updates.

- **Lazy Propagation:** Each lazy value created during updates is pushed down at most once during subsequent operations. Since O(k log n) lazy values are created total, at most O(k log n) push operations occur.

- **Range Queries:** Each query traverses O(log n) nodes in the tree. Total traversal cost: O(q log n).

- **Total Complexity:** O(k log n) + O(k log n) + O(q log n) = O(k log n + q log n).

